                    "description": "评分值是否高亮展示"
                  },
                  "scoreColorDay": {
                    "type": "string",
                    "description": "评分日间模式颜色（十六进制）"
                  },
                  "scoreColorNight": {
                    "type": "string",
                    "description": "评分夜间模式颜色（十六进制）"
                  },
                  "scorePersonCount": {
                    "type": "number",
                    "description": "评分人数"
                  },
                  "scoreCount": {
                    "type": "number",
                    "description": "评分次数"
                  },
