                      },
                      "hasLight": {
                        "type": "boolean",
                        "description": "当前用户是否已点亮该评论"
                      }
                    }
                  },
                  "schema": {
                    "type": "string",
                    "description": "跳转到评分详情的 schema 链接"
                  },
                  "hexColor": {
                    "type": "string",
