                  },
                  "maskColor": {
                    "type": "string",
                    "description": "蒙层颜色（含透明度的十六进制）"
                  },
                  "commentCount": {
                    "type": "number",
                    "description": "评论数"
                  },
                  "summedCommentCount": {
                    "type": "number",
                    "description": "累计评论数（含子项）"
                  },
                  "itemId": {
                    "type": "number",
                    "description": "评分项ID"
                  },
                  "resourceMark": {
